<script setup lang="ts">import GText from '../../content/GText/GText.vue'; import type { TextContent } from '@/shared/types/components'; withDefaults(defineProps<{ open?: boolean; disabled?: boolean; summary?: TextContent }>(), { open: false, summary: () => ({ table: 'Common', textKey: '#DETAILS' }) }); const emit = defineEmits<{ 'update:open': [value: boolean] }>(); function onToggle(event: Event) { const details = event.target as HTMLDetailsElement; if (details.open && details.dataset.disabled === 'true') details.open = false; else emit('update:open', details.open) }</script>
<template><details class="ew-disclosure" :open="open" :data-disabled="disabled" @toggle="onToggle"><summary :aria-disabled="disabled" :tabindex="disabled ? -1 : undefined" @click="disabled && $event.preventDefault()"><slot name="summary"><GText :content="summary" /></slot></summary><slot /></details></template>
